/**
 * Browser half of the aim-lab-brand bundle.
 *
 * Occupies the same slots the official brand package fills, which is the
 * supported way to replace the product identity (see ui-brand-official's
 * README: "replacing the brand means composing another package that occupies
 * the same slots").
 *
 * The home headline is NOT a slot and its locale namespace cannot be
 * re-registered (`locale namespace "conversation" already has locale "zh"`),
 * so the slogan is replaced at the DOM level after render.
 */
window.__ModuleLoader__.load({
  id: '@aim-lab/dsh-brand',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    const EMBLEM = 'data:image/png;base64,';

    /** 首页标语。 */
    const SLOGAN = '开始本次结构设计任务';

    /** 官方首页标语（中文 / 英文），命中即替换。 */
    const ORIGINAL_HEADLINES = ['探索未至之境', 'Into the Unknown'];

    /** 标识放大倍数：侧边栏（小尺寸）与首页（大尺寸）分开调。 */
    const EMBLEM_SCALE_SIDEBAR = 1.0;
    const EMBLEM_SCALE_HERO = 1.9;

    function Emblem(props) {
      const base = props && props.size ? props.size : 24;
      const isHero = base >= 30;
      const size = Math.round(base * (isHero ? EMBLEM_SCALE_HERO : EMBLEM_SCALE_SIDEBAR));
      return h('img', {
        src: EMBLEM,
        width: size,
        height: size,
        alt: '结构设计助手标识',
        draggable: false,
        style: {
          display: 'block',
          width: size + 'px',
          height: size + 'px',
          objectFit: 'contain',
          pointerEvents: 'none',
          position: 'relative',
          top: '0px',
        },
      });
    }

    function BrandName() {
      return h(
        'span',
        {
          style: {
            fontWeight: 600,
            fontSize: '12.5px',
            letterSpacing: '0.02em',
            whiteSpace: 'nowrap',
          },
        },
        '火箭总体结构辅助设计智能体',
      );
    }

    /** 就地把首页标语换成任务提示，并在 React 重渲染后再次生效。 */
    function installSlogan() {
      let scheduled = false;
      const swap = () => {
        scheduled = false;
        const nodes = document.querySelectorAll('span');
        for (let i = 0; i < nodes.length; i += 1) {
          const el = nodes[i];
          if (el.childElementCount !== 0) continue;
          const text = (el.textContent || '').trim();
          if (ORIGINAL_HEADLINES.indexOf(text) !== -1) el.textContent = SLOGAN;
        }
      };
      const schedule = () => {
        if (scheduled) return;
        scheduled = true;
        requestAnimationFrame(swap);
      };
      schedule();
      const observer = new MutationObserver(schedule);
      observer.observe(document.body, { childList: true, subtree: true });
      return () => observer.disconnect();
    }

    /** 首页大标题旁不展示标识：占住槽位但渲染空，避免回落到官方鲸鱼标。 */
    function HeroNone() {
      return null;
    }

    return {
      inject: ['slots'],
      apply(ctx) {
        ctx.slots.inject('sidebar.brand.mark', () =>
          ctx.slots.register({ name: 'sidebar.brand.mark', id: 'aim-lab-brand-mark' }, Emblem),
        );
        ctx.slots.inject('sidebar.brand.name', () =>
          ctx.slots.register({ name: 'sidebar.brand.name', id: 'aim-lab-brand-name' }, BrandName),
        );
        // 首页大标题旁不再展示标识；仍占住槽位，避免回落到官方鲸鱼标。
        ctx.slots.inject('conversation.hero.brand.mark', () =>
          ctx.slots.register(
            { name: 'conversation.hero.brand.mark', id: 'aim-lab-brand-hero' },
            HeroNone,
          ),
        );
        ctx.effect(() => installSlogan(), 'aim-lab-brand: home slogan');
      },
    };
  },
});
